with with_gaps as (select *, case when lag(reading_ts) over (partition by device_code order by reading_ts asc, id asc) is null or reading_ts > lag(reading_ts) over (partition by device_code order by reading_ts asc, id asc) + interval '20' minute then 1 else 0 end as new_group_flag from device_readings), sessions_device_readings as (select *, sum(new_group_flag) over (partition by device_code order by reading_ts asc, id asc rows between unbounded preceding and current row) as burst_id from with_gaps) select case when new_group_flag >= 1 then 'HIGH' else 'LOW' end as new_group_flag_tier, date_trunc('hour', reading_ts) as hour_window, max(new_group_flag) filter (where device_code = 'DV-04') as dv_04_max_new_group_flag, round(avg(humidity), 2) as avg_humidity, min(reading_ts) as first_seen, max(burst_id) as max_burst_id, sum(pressure) as total_pressure, grouping_id() as grouping_id from sessions_device_readings group by cube (case when new_group_flag >= 1 then 'HIGH' else 'LOW' end, date_trunc('hour', reading_ts))
